/// Danh sách các món ăn chưa có ảnh chính thức, đang ở trạng thái pending chờ AI/ảnh đạt chuẩn.
const Set<String> kPendingFoodIds = {
  'com_ga_xoi_mo',
  'com_rang_dua_bo',
  'canh_bi_xanh_thit_bam',
  'sua_dau_nanh_hop_fami',
  'mass_gainer_1_scoop',
  'casein_protein_1_scoop',
};

/// Kiểm tra một món ăn có đang ở trạng thái pending (chưa có ảnh) hay không.
bool isFoodImagePending(String foodName) {
  final id = kFoodImageIdByName[foodName.trim()];
  return id != null && kPendingFoodIds.contains(id);
}

/// Returns the bundled asset path for [foodName], or null when the food
/// has no curated image (e.g. user-created foods or pending foods).
String? foodImageAssetFor(String foodName) {
  final id = kFoodImageIdByName[foodName.trim()];
  if (id == null || kPendingFoodIds.contains(id)) {
    return null;
  }
  return '$kFoodImageAssetDir/food_$id.jpg';
}
